
const REMAIN = [{"xsId": "110:7489", "frameName": "check \u00b7 bold", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" id=\"Check-1--Streamline-Ultimate\">\n  <desc>\n    Check 1 Streamline Icon: https://streamlinehq.com\n  </desc>\n  <path d=\"M23.37 0.29a1.49 1.49 0 0 0 -2.09 0.34L7.25 20.2l-4.69 -4.69a1.5 1.5 0 0 0 -2.12 2.12l5.93 5.94a1.53 1.53 0 0 0 2.28 -0.19l15.07 -21a1.49 1.49 0 0 0 -0.35 -2.09Z\" fill=\"#000000\" stroke-width=\"1\"></path>\n</svg>"}, {"xsId": "110:7527", "frameName": "close.alt \u00b7 bold", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" id=\"Close--Streamline-Ultimate\">\n  <desc>\n    Close Streamline Icon: https://streamlinehq.com\n  </desc>\n  <path d=\"M14.3 12.18a0.24 0.24 0 0 1 0 -0.35l9.26 -9.27a1.49 1.49 0 0 0 0 -2.12 1.51 1.51 0 0 0 -2.12 0L12.18 9.7a0.25 0.25 0 0 1 -0.36 0L2.56 0.44a1.51 1.51 0 0 0 -2.12 0 1.49 1.49 0 0 0 0 2.12l9.26 9.27a0.24 0.24 0 0 1 0 0.35L0.44 21.44a1.49 1.49 0 0 0 0 2.12 1.51 1.51 0 0 0 2.12 0l9.26 -9.26a0.25 0.25 0 0 1 0.36 0l9.26 9.26a1.51 1.51 0 0 0 2.12 0 1.49 1.49 0 0 0 0 -2.12Z\" fill=\"#000000\" stroke-width=\"1\"></path>\n</svg>"}, {"xsId": "111:4130", "frameName": "error \u00b7 bold", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" id=\"Remove-Circle--Streamline-Ultimate\">\n  <desc>\n    Remove Circle Streamline Icon: https://streamlinehq.com\n  </desc>\n  <path d=\"M12 0a12 12 0 1 0 12 12A12 12 0 0 0 12 0m5.49 16.07a1 1 0 0 1 -1.41 1.42l-3.9 -3.9a0.25 0.25 0 0 0 -0.36 0l-3.9 3.9a1 1 0 1 1 -1.41 -1.42l3.9 -3.89a0.25 0.25 0 0 0 0 -0.36l-3.9 -3.9a1 1 0 0 1 1.41 -1.41l3.9 3.9a0.25 0.25 0 0 0 0.36 0l3.9 -3.9a1 1 0 0 1 1.41 1.41l-3.9 3.9a0.25 0.25 0 0 0 0 0.36Z\" fill=\"#000000\" stroke-width=\"1\"></path>\n</svg>"}, {"xsId": "111:4407", "frameName": "star \u00b7 bold", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" id=\"Rating-Star--Streamline-Ultimate\">\n  <desc>\n    Rating Star Streamline Icon: https://streamlinehq.com\n  </desc>\n  <path d=\"M23.56 8.73a1.51 1.51 0 0 0 -1.41 -1h-6.09a0.5 0.5 0 0 1 -0.47 -0.33l-2.18 -6.2A1.52 1.52 0 0 0 12 0.25a1.49 1.49 0 0 0 -1.4 1L8.41 7.42a0.5 0.5 0 0 1 -0.47 0.33H1.85a1.5 1.5 0 0 0 -1.41 1 1.52 1.52 0 0 0 0.45 1.65l5.18 4.3a0.5 0.5 0 0 1 0.16 0.54l-2.18 6.53a1.5 1.5 0 0 0 2.31 1.69l5.34 -3.92a0.49 0.49 0 0 1 0.59 0l5.35 3.92A1.5 1.5 0 0 0 20 21.77l-2.18 -6.53a0.5 0.5 0 0 1 0.16 -0.54l5.19 -4.31a1.51 1.51 0 0 0 0.39 -1.66\" fill=\"#000000\" stroke-width=\"1\"></path>\n</svg>"}, {"xsId": "111:4445", "frameName": "success \u00b7 bold", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" id=\"Check-Circle--Streamline-Ultimate\">\n  <desc>\n    Check Circle Streamline Icon: https://streamlinehq.com\n  </desc>\n  <g>\n    <path d=\"M12.84 18.32a3 3 0 0 1 -4.45 0.24L4.87 15a3.1 3.1 0 0 1 -0.23 -4.24A3 3 0 0 1 9 10.68l1.08 1.08a0.25 0.25 0 0 0 0.37 0l4.44 -5.51a0.25 0.25 0 0 0 -0.07 -0.37 9.67 9.67 0 0 0 -6.28 -1.37 9.75 9.75 0 1 0 10.83 11.35 9.89 9.89 0 0 0 -0.32 -4.62 0.26 0.26 0 0 0 -0.44 -0.08Z\" fill=\"#000000\" stroke-width=\"1\"></path>\n    <path d=\"M23.44 0.39a1.5 1.5 0 0 0 -2.11 0.23L10.39 14.2l-2.46 -2.46a1.51 1.51 0 0 0 -2.12 0 1.49 1.49 0 0 0 0 2.12l3.64 3.64a1.51 1.51 0 0 0 2.22 -0.12l12 -14.88a1.51 1.51 0 0 0 -0.23 -2.11\" fill=\"#000000\" stroke-width=\"1\"></path>\n  </g>\n</svg>"}];

const page = figma.root.children.find(p => /Icons/i.test(p.name));
await figma.setCurrentPageAsync(page);

const collections = await figma.variables.getLocalVariableCollectionsAsync();
let iconDefault = null;
for (const coll of collections) {
  for (const id of coll.variableIds) {
    const v = await figma.variables.getVariableByIdAsync(id);
    if (v && v.name === 'icon/default') iconDefault = v;
  }
}
if (!iconDefault) throw new Error('icon/default missing');

function bindFills(root) {
  const stack = [root];
  while (stack.length) {
    const n = stack.pop();
    if ('constraints' in n) n.constraints = { horizontal: 'SCALE', vertical: 'SCALE' };
    if (n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION' || n.type === 'ELLIPSE' || n.type === 'STAR' || n.type === 'POLYGON') {
      const paint = figma.variables.setBoundVariableForPaint(
        { type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', iconDefault);
      n.fills = [paint];
      n.strokes = [];
    }
    if ('children' in n) for (const c of n.children) stack.push(c);
  }
}

function applyBoldToXs(xs, svg, frameName) {
  for (const c of [...xs.children]) c.remove();
  const node = figma.createNodeFromSvg(svg);
  node.name = frameName;
  try { node.resize(16, 16); } catch (_) {}
  node.x = 0; node.y = 0;
  node.clipsContent = false;
  if ('constraints' in node) node.constraints = { horizontal: 'SCALE', vertical: 'SCALE' };
  xs.appendChild(node);
  bindFills(node);
  // Upscale undersized single vectors (stars etc.)
  const vectors = node.findAll(n => n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION');
  if (vectors.length === 1) {
    const v = vectors[0];
    if (v.width < 14 || v.height < 14) {
      const target = 15;
      const scale = Math.min(target / v.width, target / v.height);
      const nw = v.width * scale, nh = v.height * scale;
      v.resize(nw, nh);
      v.x = (16 - nw) / 2;
      v.y = (16 - nh) / 2;
    }
  }
  try { xs.resizeWithoutConstraints(16, 16); } catch (_) { try { xs.resize(16, 16); } catch (__) {} }
  xs.clipsContent = false;
  return true;
}

const remainResults = [];
for (const item of REMAIN) {
  const xs = await figma.getNodeByIdAsync(item.xsId);
  if (!xs) { remainResults.push({ id: item.xsId, ok: false }); continue; }
  applyBoldToXs(xs, item.svg, item.frameName);
  remainResults.push({ id: item.xsId, frame: item.frameName, ok: true });
}

// Fix info: rename 16px misnamed Size=md → Size=xs
const infoSet = await figma.getNodeByIdAsync('132:5955');
let infoRename = null;
if (infoSet) {
  const misnamed = infoSet.children.find(c => c.width === 16 && c.name !== 'Size=xs');
  if (misnamed) {
    const old = misnamed.name;
    misnamed.name = 'Size=xs';
    infoRename = { id: misnamed.id, from: old, to: 'Size=xs' };
  }
}

// Catalog visibility: show Size=xs only (bold), hide other sizes
let shown = 0, hidden = 0, sets = 0;
for (const set of page.findAll(n => n.type === 'COMPONENT_SET')) {
  if (!/^icon\//.test(set.name)) continue;
  sets++;
  for (const v of set.children) {
    const isXs = v.name === 'Size=xs' || (v.width === 16 && v.height === 16);
    if (isXs) {
      v.visible = true;
      shown++;
      // ensure name
      if (v.name !== 'Size=xs') v.name = 'Size=xs';
    } else {
      v.visible = false;
      hidden++;
    }
  }
  try { set.resizeWithoutConstraints(16, 16); } catch (_) {
    try { set.resize(16, 16); } catch (__) {}
  }
  set.clipsContent = true;
}

// Re-audit stroke xs
const stillStroke = [];
function classify(comp) {
  const vectors = comp.findAll(n => n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION');
  let fillN = 0, strokeN = 0;
  for (const v of vectors) {
    if (v.fills && v.fills !== figma.mixed && v.fills.length) fillN++;
    if (v.strokes && v.strokes.length) strokeN++;
  }
  if (strokeN > 0 && fillN === 0) return 'stroke';
  if (fillN > 0 && strokeN === 0) return 'fill';
  if (fillN > 0 && strokeN > 0) return 'mixed';
  return 'other';
}
for (const set of page.findAll(n => n.type === 'COMPONENT_SET')) {
  if (!/^icon\//.test(set.name)) continue;
  const xs = set.children.find(c => c.name === 'Size=xs');
  if (!xs) continue;
  const kind = classify(xs);
  if (kind !== 'fill') stillStroke.push({ set: set.name, kind, xsId: xs.id });
}

return { remainResults, infoRename, catalog: { sets, shown, hidden }, stillStroke };
